content.content:
     1→<% content_for :title, "Dashboard Anggota - Sportifa" %>
     2→
     3→<div class="member-dashboard-page" data-controller="absence-modal">
     4→  <div class="dashboard-container max-w-7xl mx-auto">
     5→  
     6→  <!-- Header -->
     7→  <div class="dashboard-header">
     8→    <div class="header-content">
     9→      <div class="header-text">
    10→        <h1 class="page-title">👤 Dashboard Anggota</h1>
    11→        <p class="page-subtitle">Selamat datang kembali, <%= current_user.first_name %>!</p>
    12→      </div>
    13→      <div class="header-actions">
    14→        <%= form_with url: logout_path, method: :delete, local: true, class: "inline-form" do |form| %>
    15→          <%= form.submit "Keluar", class: "btn btn-outline" %>
    16→        <% end %>
    17→      </div>
    18→    </div>
    19→  </div>
    20→
    21→  <!-- Quick Stats -->
    22→  <div class="stats-grid">
    23→    <div class="stat-card stat-primary">
    24→      <div class="stat-icon">🏃</div>
    25→      <div class="stat-content">
    26→        <div class="stat-value"><%= @memberships.count + @trial_memberships.count %></div>
    27→        <div class="stat-label">Kelas Aktif</div>
    28→      </div>
    29→    </div>
    30→    <div class="stat-card stat-success">
    31→      <div class="stat-icon">✓</div>
    32→      <div class="stat-content">
    33→        <div class="stat-value"><%= @recent_clock_ins.clocked_out.count %></div>
    34→        <div class="stat-label">Sesi Minggu Ini</div>
    35→      </div>
    36→    </div>
    37→    <%= link_to member_children_path, class: "stat-card stat-info stat-link" do %>
    38→      <div class="stat-icon">👨‍👩‍👧‍👦</div>
    39→      <div class="stat-content">
    40→        <div class="stat-value"><%= current_user.children.count %></div>
    41→        <div class="stat-label">Profil Anak</div>
    42→      </div>
    43→    <% end %>
    44→  </div>
    45→
    46→  <!-- Trial Memberships Alert -->
    47→  <% if @trial_memberships.any? %>
    48→    <div class="alert alert-warning">
    49→      <span class="alert-icon">🏃‍♂️</span>
    50→      <div class="alert-content">
    51→        <h4>Keanggotaan Trial</h4>
    52→        <% @trial_memberships.each do |membership| %>
    53→          <p class="mb-0">
    54→            <strong><%= membership.sport_class.name %></strong>
    55→            <% if membership.trial_ends_at %>
    56→              - Trial berakhir <%= membership.trial_ends_at.strftime("%d %b %Y") %>
    57→            <% end %>
    58→          </p>
    59→        <% end %>
    60→      </div>
    61→    </div>
    62→  <% end %>
    63→
    64→  <!-- Today's Schedule -->
    65→  <div class="card card-modern">
    66→    <div class="card-header">
    67→      <div class="card-header-content">
    68→        <div>
    69→          <h3>📅 Jadwal Hari Ini</h3>
    70→          <p class="text-muted"><%= Date.current.strftime("%A, %d %B %Y") %></p>
    71→        </div>
    72→      </div>
    73→    </div>
    74→    <div class="card-body">
    75→      <% if @upcoming_schedules.any? %>
    76→        <div class="schedules-list">
    77→          <% @upcoming_schedules.each do |schedule| %>
    78→            <div class="schedule-item">
    79→              <div class="schedule-info">
    80→                <h4><%= schedule.sport_class.name %></h4>
    81→                <p class="schedule-meta">
    82→                  🕐 <%= schedule.time_range %> • 📍 <%= schedule.sport_class.location %>
    83→                </p>
    84→                <span class="badge badge-info"><%= schedule.sport_class.sport_type %></span>
    85→              </div>
    86→              <div class="schedule-actions">
    87→                <% clock_in = current_user.clock_ins.where(schedule: schedule).where("DATE(created_at) = ?", Date.current).first %>
    88→                <% if clock_in&.excused? %>
    89→                  <span class="badge badge-warning">🏥 Tidak Hadir</span>
    90→                <% elsif clock_in&.clocked_out? %>
    91→                  <span class="badge badge-success">✓ Selesai</span>
    92→                <% elsif clock_in&.clocked_in? %>
    93→                  <%= button_to member_clock_out_path(clock_in), method: :patch, class: "btn btn-danger btn-sm", data: { turbo: false } do %>
    94→                    <span class="btn-icon">⏹</span>
    95→                    <span class="btn-text">Absen Keluar</span>
    96→                  <% end %>
    97→                <% else %>
    98→                  <div class="action-buttons-group">
    99→                    <%= button_to member_clock_in_path(schedule), method: :post, class: "btn btn-success btn-sm", data: { turbo: false } do %>
   100→                      <span class="btn-icon">▶</span>
   101→                      <span class="btn-text">Absen Masuk</span>
   102→                    <% end %>
   103→                    <button type="button" 
   104→                            class="btn btn-outline btn-sm" 
   105→                            data-action="click->absence-modal#open"
   106→                            data-schedule-id="<%= schedule.id %>"
   107→                            data-schedule-name="<%= schedule.sport_class.name %>">
   108→                      <span class="btn-icon">🏥</span>
   109→                      <span class="btn-text">Tidak Bisa Hadir</span>
   110→                    </button>
   111→                  </div>
   112→                <% end %>
   113→              </div>
   114→            </div>
   115→          <% end %>
   116→        </div>
   117→      <% else %>
   118→        <div class="empty-state">
   119→          <div class="empty-icon">📅</div>
   120→          <h4>Tidak Ada Kelas Hari Ini</h4>
   121→          <p class="text-muted">Tidak ada kelas yang dijadwalkan untuk hari ini</p>
   122→          <%= link_to member_classes_path, class: "btn btn-primary" do %>
   123→            <span class="btn-icon">🔍</span>
   124→            <span class="btn-text">Jelajahi Kelas</span>
   125→          <% end %>
   126→        </div>
   127→      <% end %>
   128→    </div>
   129→  </div>
   130→
   131→  <!-- My Classes -->
   132→  <div class="card card-modern">
   133→    <div class="card-header">
   134→      <div class="card-header-content">
   135→        <div>
   136→          <h3>🏆 Kelas Saya</h3>
   137→          <p class="text-muted">Keanggotaan aktif Anda</p>
   138→        </div>
   139→        <%= link_to member_classes_path, class: "btn btn-outline btn-sm" do %>
   140→          <span class="btn-icon">🔍</span>
   141→          <span class="btn-text">Jelajahi</span>
   142→        <% end %>
   143→      </div>
   144→    </div>
   145→    <div class="card-body">
   146→      <% if @memberships.any? %>
   147→        <div class="classes-grid">
   148→          <% @memberships.each do |membership| %>
   149→            <div class="class-card">
   150→              <div class="class-header">
   151→                <h4><%= membership.sport_class.name %></h4>
   152→                <div class="class-badges">
   153→                  <span class="badge badge-<%= membership.active? ? 'success' : 'warning' %>">
   154→                    <%= membership.status.humanize %>
   155→                  </span>
   156→                  <span class="badge badge-info"><%= membership.sport_class.sport_type %></span>
   157→                </div>
   158→              </div>
   159→              <p class="class-meta">
   160→                📍 <%= membership.sport_class.location %> • 
   161→                💰 Rp <%= number_to_currency(membership.sport_class.price, unit: "", precision: 0, delimiter: ".") %>/bulan
   162→              </p>
   163→              <div class="class-footer">
   164→                <p class="text-sm text-muted">Bergabung <%= membership.joined_at&.strftime("%d %b %Y") || "-" %></p>
   165→              </div>
   166→            </div>
   167→          <% end %>
   168→        </div>
   169→      <% else %>
   170→        <div class="empty-state">
   171→          <div class="empty-icon">🏃</div>
   172→          <h4>Belum Ada Kelas</h4>
   173→          <p class="text-muted">Anda belum bergabung dengan kelas apapun</p>
   174→          <%= link_to member_classes_path, class: "btn btn-primary" do %>
   175→            <span class="btn-icon">🔍</span>
   176→            <span class="btn-text">Cari Kelas</span>
   177→          <% end %>
   178→        </div>
   179→      <% end %>
   180→    </div>
   181→  </div>
   182→
   183→  <!-- Recent Activity -->
   184→  <div class="card card-modern">
   185→    <div class="card-header">
   186→      <h3>🔥 Aktivitas Terbaru</h3>
   187→    </div>
   188→    <div class="card-body">
   189→      <% if @recent_clock_ins.any? %>
   190→        <div class="activity-list">
   191→          <% @recent_clock_ins.each do |clock_in| %>
   192→            <div class="activity-item">
   193→              <div class="activity-info">
   194→                <h5><%= clock_in.schedule.sport_class.name %></h5>
   195→                <p class="activity-meta">
   196→                  <%= clock_in.created_at.strftime("%d/%m at %H:%M") %>
   197→                  <% if clock_in.clocked_out? %>
   198→                    • <%= clock_in.duration_formatted %>
   199→                  <% elsif clock_in.excused? && clock_in.excuse_reason.present? %>
   200→                    <br><small class="text-muted">Alasan: <%= truncate(clock_in.excuse_reason, length: 50) %></small>
   201→                  <% end %>
   202→                </p>
   203→              </div>
   204→              <span class="badge badge-<%= clock_in.clocked_out? ? 'success' : clock_in.excused? ? 'secondary' : 'warning' %>">
   205→                <%= clock_in.excused? ? '🏥 Tidak Hadir' : clock_in.status.humanize %>
   206→              </span>
   207→            </div>
   208→          <% end %>
   209→        </div>
   210→      <% else %>
   211→        <div class="empty-state small">
   212→          <p class="text-muted">Tidak ada aktivitas terbaru</p>
   213→        </div>
   214→      <% end %>
   215→    </div>
   216→  </div>
   217→
   218→  <!-- Performance Summary -->
   219→  <% if @performance_summary.any? %>
   220→    <div class="card card-modern">
   221→      <div class="card-header">
   222→        <h3>📈 Ringkasan Kinerja</h3>
   223→      </div>
   224→      <div class="card-body">
   225→        <div class="performance-grid">
   226→          <div class="performance-item">
   227→            <h4 class="text-primary"><%= @performance_summary[:average_skill_level] || "N/A" %></h4>
   228→            <p class="text-muted">Tingkat Kemahiran Rata-rata</p>
   229→          </div>
   230→          <div class="performance-item">
   231→            <h4 class="text-success"><%= @performance_summary[:attendance_rate] || "0" %>%</h4>
   232→            <p class="text-muted">Tingkat Kehadiran</p>
   233→          </div>
   234→        </div>
   235→      </div>
   236→    </div>
   237→  <% end %>
   238→
   239→  <!-- Absence Reporting Modal -->
   240→  <div data-absence-modal-target="modal" 
   241→       class="modal-overlay" 
   242→       data-action="click->absence-modal#closeOnOutsideClick">
   243→    <div class="modal-content">
   244→      <div class="modal-header">
   245→        <h3 class="modal-title">🏥 Laporkan Ketidakhadiran</h3>
   246→        <button type="button" 
   247→                class="modal-close" 
   248→                data-action="click->absence-modal#close">&times;</button>
   249→      </div>
   250→      
   251→      <%= form_with url: "#", method: :post, data: { absence_modal_target: "form" }, local: true do |form| %>
   252→        <div class="form-group">
   253→          <label class="form-label required">Nama Kelas</label>
   254→          <input type="text" 
   255→                 data-absence-modal-target="className" 
   256→                 class="form-control" 
   257→                 readonly>
   258→        </div>
   259→
   260→        <div class="form-group">
   261→          <label for="excuse_reason" class="form-label required">Alasan Ketidakhadiran</label>
   262→          <%= form.text_area :excuse_reason, 
   263→              class: "form-control", 
   264→              rows: 4,
   265→              required: true,
   266→              placeholder: "Contoh: Sakit, urusan keluarga, atau alasan lainnya..." %>
   267→          <small class="form-text text-muted">
   268→            Harap berikan alasan yang jelas agar pelatih dapat memahami situasi Anda.
   269→          </small>
   270→        </div>
   271→
   272→        <div class="form-actions" style="display: flex; gap: 1rem; margin-top: 1.5rem;">
   273→          <%= form.submit "Laporkan Ketidakhadiran", class: "btn btn-primary", style: "flex: 1;" %>
   274→          <button type="button" 
   275→                  data-action="click->absence-modal#close" 
   276→                  class="btn btn-outline" 
   277→                  style="flex: 1;">Batal</button>
   278→        </div>
   279→      <% end %>
   280→    </div>
   281→  </div>
   282→
   283→  </div><!-- End dashboard-container -->
   284→</div><!-- End member-dashboard-page -->
   285→
   286→<style>
   287→  /* ============================================
   288→     MODERN MEMBER DASHBOARD DESIGN
   289→     ============================================ */
   290→
   291→  /* Page Container */
   292→  .member-dashboard-page {
   293→    min-height: 100vh;
   294→    background: linear-gradient(135deg, #f5f7fa 0%, #e8eef5 100%);
   295→    padding: 3rem 2rem;
   296→  }
   297→
   298→  .dashboard-container {
   299→    max-width: 1400px;
   300→    margin: 0 auto;
   301→    width: 100%;
   302→    padding: 0 1rem;
   303→  }
   304→
   305→  /* Header Section */
   306→  .dashboard-header {
   307→    margin-bottom: 2rem;
   308→    animation: fadeInDown 0.5s ease-out;
   309→  }
   310→
   311→  @keyframes fadeInDown {
   312→    from {
   313→      opacity: 0;
   314→      transform: translateY(-20px);
   315→    }
   316→    to {
   317→      opacity: 1;
   318→      transform: translateY(0);
   319→    }
   320→  }
   321→
   322→  .header-content {
   323→    background: white;
   324→    border-radius: 20px;
   325→    padding: 2.5rem 3rem;
   326→    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
   327→    display: flex;
   328→    justify-content: space-between;
   329→    align-items: center;
   330→    flex-wrap: wrap;
   331→    gap: 1.5rem;
   332→  }
   333→
   334→  .header-text {
   335→    flex: 1;
   336→    min-width: 250px;
   337→  }
   338→
   339→  .page-title {
   340→    font-size: 2rem;
   341→    font-weight: 800;
   342→    color: #1a202c;
   343→    margin: 0 0 0.5rem 0;
   344→    letter-spacing: -0.5px;
   345→  }
   346→
   347→  .page-subtitle {
   348→    font-size: 1rem;
   349→    color: #718096;
   350→    margin: 0;
   351→    font-weight: 400;
   352→  }
   353→
   354→  .header-actions {
   355→    display: flex;
   356→    gap: 1rem;
   357→    flex-wrap: wrap;
   358→  }
   359→
   360→  .inline-form {
   361→    display: inline;
   362→  }
   363→
   364→  .btn {
   365→    display: inline-flex;
   366→    align-items: center;
   367→    gap: 0.5rem;
   368→    padding: 0.75rem 1.5rem;
   369→    border-radius: 12px;
   370→    font-weight: 600;
   371→    font-size: 0.95rem;
   372→    text-decoration: none;
   373→    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
   374→    cursor: pointer;
   375→    border: none;
   376→    white-space: nowrap;
   377→  }
   378→
   379→  .btn-primary {
   380→    background: linear-gradient(135deg, #1E88E5 0%, #1976D2 100%);
   381→    color: white;
   382→    box-shadow: 0 4px 15px rgba(30,136,229,0.3);
   383→  }
   384→
   385→  .btn-primary:hover {
   386→    transform: translateY(-2px);
   387→    box-shadow: 0 6px 25px rgba(30,136,229,0.4);
   388→  }
   389→
   390→  .btn-outline {
   391→    background: white;
   392→    color: #4a5568;
   393→    border: 2px solid #e2e8f0;
   394→  }
   395→
   396→  .btn-outline:hover {
   397→    border-color: #1E88E5;
   398→    color: #1E88E5;
   399→    transform: translateY(-2px);
   400→    box-shadow: 0 4px 15px rgba(30,136,229,0.15);
   401→  }
   402→
   403→  .btn-success {
   404→    background: linear-gradient(135deg, #8BC34A 0%, #7CB342 100%);
   405→    color: white;
   406→    box-shadow: 0 4px 15px rgba(139,195,74,0.3);
   407→  }
   408→
   409→  .btn-success:hover {
   410→    transform: translateY(-2px);
   411→    box-shadow: 0 6px 25px rgba(139,195,74,0.4);
   412→  }
   413→
   414→  .btn-danger {
   415→    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
   416→    color: white;
   417→    box-shadow: 0 4px 15px rgba(239,68,68,0.3);
   418→  }
   419→
   420→  .btn-danger:hover {
   421→    transform: translateY(-2px);
   422→    box-shadow: 0 6px 25px rgba(239,68,68,0.4);
   423→  }
   424→
   425→  .btn-sm {
   426→    padding: 0.5rem 1rem;
   427→    font-size: 0.875rem;
   428→  }
   429→
   430→  .btn-icon {
   431→    font-size: 1.2rem;
   432→    line-height: 1;
   433→  }
   434→
   435→  /* Stats Grid */
   436→  .stats-grid {
   437→    display: grid;
   438→    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
   439→    gap: 1.5rem;
   440→    margin-bottom: 2rem;
   441→    animation: fadeInUp 0.6s ease-out 0.2s both;
   442→  }
   443→
   444→  @keyframes fadeInUp {
   445→    from {
   446→      opacity: 0;
   447→      transform: translateY(20px);
   448→    }
   449→    to {
   450→      opacity: 1;
   451→      transform: translateY(0);
   452→    }
   453→  }
   454→
   455→  .stat-card {
   456→    background: white;
   457→    border-radius: 16px;
   458→    padding: 2rem 1.5rem;
   459→    display: flex;
   460→    align-items: center;
   461→    gap: 1.25rem;
   462→    box-shadow: 0 4px 15px rgba(0,0,0,0.08);
   463→    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
   464→    border: 2px solid transparent;
   465→  }
   466→
   467→  .stat-card:hover {
   468→    transform: translateY(-4px);
   469→    box-shadow: 0 8px 25px rgba(0,0,0,0.12);
   470→  }
   471→
   472→  .stat-card.stat-link {
   473→    cursor: pointer;
   474→    text-decoration: none;
   475→    color: inherit;
   476→  }
   477→
   478→  .stat-card.stat-primary {
   479→    border-color: #1E88E5;
   480→  }
   481→
   482→  .stat-card.stat-success {
   483→    border-color: #8BC34A;
   484→  }
   485→
   486→  .stat-card.stat-info {
   487→    border-color: #00BCD4;
   488→  }
   489→
   490→  .stat-icon {
   491→    font-size: 2.5rem;
   492→    width: 60px;
   493→    height: 60px;
   494→    display: flex;
   495→    align-items: center;
   496→    justify-content: center;
   497→    border-radius: 12px;
   498→    background: linear-gradient(135deg, #f5f7fa 0%, #e8eef5 100%);
   499→  }
   500→
   501→  .stat-content {
   502→    flex: 1;
   503→  }
   504→
   505→  .stat-value {
   506→    font-size: 2rem;
   507→    font-weight: 800;
   508→    color: #1a202c;
   509→    line-height: 1;
   510→    margin-bottom: 0.5rem;
   511→  }
   512→
   513→  .stat-label {
   514→    font-size: 0.875rem;
   515→    color: #718096;
   516→    font-weight: 500;
   517→    text-transform: uppercase;
   518→    letter-spacing: 0.5px;
   519→  }
   520→
   521→  /* Alert */
   522→  .alert {
   523→    display: flex;
   524→    align-items: flex-start;
   525→    gap: 1rem;
   526→    padding: 1.5rem;
   527→    border-radius: 12px;
   528→    margin-bottom: 2rem;
   529→    animation: slideIn 0.4s ease-out;
   530→  }
   531→
   532→  @keyframes slideIn {
   533→    from {
   534→      opacity: 0;
   535→      transform: translateX(-20px);
   536→    }
   537→    to {
   538→      opacity: 1;
   539→      transform: translateX(0);
   540→    }
   541→  }
   542→
   543→  .alert-warning {
   544→    background: linear-gradient(135deg, #fff3cd 0%, #ffe69c 100%);
   545→    border: 2px solid #FFC107;
   546→    color: #856404;
   547→  }
   548→
   549→  .alert-icon {
   550→    font-size: 1.5rem;
   551→    flex-shrink: 0;
   552→  }
   553→
   554→  .alert-content {
   555→    flex: 1;
   556→  }
   557→
   558→  .alert-content h4 {
   559→    margin: 0 0 0.75rem 0;
   560→    font-size: 1.1rem;
   561→    font-weight: 700;
   562→  }
   563→
   564→  .alert-content p {
   565→    margin: 0.5rem 0;
   566→  }
   567→
   568→  /* Cards */
   569→  .card-modern {
   570→    background: white;
   571→    border-radius: 20px;
   572→    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
   573→    overflow: hidden;
   574→    margin-bottom: 2rem;
   575→    animation: fadeInUp 0.6s ease-out 0.4s both;
   576→  }
   577→
   578→  .card-header {
   579→    background: linear-gradient(135deg, #f9fafb 0%, #f3f4f6 100%);
   580→    padding: 1.5rem 2rem;
   581→    border-bottom: 2px solid #e5e7eb;
