  /* Add Child Button and Children Display */
  .btn-add-child {
    margin-top: 0.75rem;
    width: 100%;
  }

  .class-children {
    margin: 1rem 0;
    padding: 1rem;
    background: #f0f9ff;
    border-radius: 8px;
    border-left: 3px solid #1E88E5;
  }

  .children-label {
    font-size: 0.875rem;
    font-weight: 600;
    color: #1a202c;
