import { Controller } from "@hotwired/stimulus"

// Connects to data-controller="absence-modal"
export default class extends Controller {
  static targets = ["modal", "form", "className"]
  static values = {
    scheduleId: Number,
    scheduleName: String
  }

  connect() {
    // Bind escape key handler
    this.handleEscape = this.handleEscape.bind(this)
  }

  open(event) {
    // Get schedule data from button
    const button = event.currentTarget
    const scheduleId = button.dataset.scheduleId
    const scheduleName = button.dataset.scheduleName

    // Check if targets exist
    if (this.hasFormTarget && this.hasClassNameTarget && this.hasModalTarget) {
      // Update form action and class name
      this.formTarget.action = `/member/report_absence/${scheduleId}`
      this.classNameTarget.value = scheduleName

      // Show modal
      this.modalTarget.classList.add("active")
      document.body.style.overflow = "hidden"

      // Add escape key listener
      document.addEventListener("keydown", this.handleEscape)
    } else {
      console.error("Absence modal targets not found. Make sure modal is on the page.")
    }
  }

  close() {
    if (this.hasModalTarget) {
      this.modalTarget.classList.remove("active")
      document.body.style.overflow = ""

      // Remove escape key listener
      document.removeEventListener("keydown", this.handleEscape)

      // Reset form if it exists
      if (this.hasFormTarget) {
        this.formTarget.reset()
      }
    }
  }

  closeOnOutsideClick(event) {
    // Only close if clicking the overlay itself, not its children
    if (event.target === this.modalTarget) {
      this.close()
    }
  }

  handleEscape(event) {
    if (event.key === "Escape") {
      this.close()
    }
  }

  disconnect() {
    // Cleanup: remove event listener if controller is disconnected while modal is open
    document.removeEventListener("keydown", this.handleEscape)
  }
}

