import { Controller } from "@hotwired/stimulus"

// Connects to data-controller="add-child-modal"
export default class extends Controller {
  static targets = ["modal", "form", "className", "childOption", "submitButton"]
  static values = {
    sportClassId: Number,
    sportClassName: String
  }

  connect() {
    // Bind escape key handler
    this.handleEscape = this.handleEscape.bind(this)
  }

  open(event) {
    // Get sport class data from button
    const button = event.currentTarget
    const sportClassId = parseInt(button.dataset.sportClassId)
    const sportClassName = button.dataset.sportClassName

    // Store values
    this.sportClassIdValue = sportClassId
    this.sportClassNameValue = sportClassName

    // Check if targets exist
    if (this.hasFormTarget && this.hasClassNameTarget && this.hasModalTarget) {
      // Update form action and class name
      this.formTarget.action = `/member/classes/${sportClassId}/add_child`
      this.classNameTarget.textContent = sportClassName

      // Show all child options
      if (this.hasChildOptionTarget) {
        this.childOptionTargets.forEach(option => {
          option.style.display = 'flex'
        })

        // Select first visible radio button by default
        const firstRadio = this.childOptionTargets[0]?.querySelector('input[type="radio"]')
        if (firstRadio) {
          firstRadio.checked = true
        }
      }

      // Show modal
      this.modalTarget.classList.add("active")
      document.body.style.overflow = "hidden"

      // Add escape key listener
      document.addEventListener("keydown", this.handleEscape)
    } else {
      console.error("Add child modal targets not found. Make sure modal is on the page.")
    }
  }

  close() {
    if (this.hasModalTarget) {
      this.modalTarget.classList.remove("active")
      document.body.style.overflow = ""

      // Remove escape key listener
      document.removeEventListener("keydown", this.handleEscape)

      // Reset form if it exists
      if (this.hasFormTarget) {
        this.formTarget.reset()
      }

      // Clear stored values
      this.sportClassIdValue = null
      this.sportClassNameValue = null
    }
  }

  closeOnOutsideClick(event) {
    // Only close if clicking the overlay itself, not its children
    if (event.target === this.modalTarget) {
      this.close()
    }
  }

  handleEscape(event) {
    if (event.key === "Escape") {
      this.close()
    }
  }

  confirmSubmit(event) {
    // Get selected child radio button
    const selectedRadio = this.formTarget.querySelector('input[name="child_id"]:checked')

    if (!selectedRadio) {
      alert('Silakan pilih anak terlebih dahulu')
      event.preventDefault()
      return
    }

    // Get child name from the closest child option
    const childOption = selectedRadio.closest('[data-add-child-modal-target="childOption"]')
    const childName = childOption?.querySelector('.child-name')?.textContent.trim()

    // Confirm action
    const confirmed = confirm(`Tambahkan ${childName} ke ${this.sportClassNameValue}?`)

    if (!confirmed) {
      event.preventDefault()
    }
  }

  disconnect() {
    // Cleanup: remove event listener if controller is disconnected while modal is open
    document.removeEventListener("keydown", this.handleEscape)
  }
}

