  before_action :require_member

  def index
    @sport_classes = SportClass.active
                               .includes(:user, :schedules, :memberships)
                               .order(:sport_type, :name)

    @my_memberships = current_user.memberships.includes(:sport_class).index_by(&:sport_class_id)
    @children = current_user.children.ordered_by_age

    # Filter by sport type if provided
    if params[:sport_type].present?
      @sport_classes = @sport_classes.by_sport_type(params[:sport_type])
    end

    @sport_types = SportClass.active.distinct.pluck(:sport_type).sort
  end
end

