class Member::SportClassesController < ApplicationController
  before_action :require_member

  def index
    @sport_classes = SportClass.active
                               .includes(:user, :schedules, :memberships)
                               .order(:sport_type, :name)

    @my_memberships = current_user.memberships.includes(:sport_class).index_by(&:sport_class_id)
    @children = current_user.children.ordered_by_age

    # Filter by sport type if provided
    if params[:sport_type].present?
      @sport_classes = @sport_classes.by_sport_type(params[:sport_type])
    end

    @sport_types = SportClass.active.distinct.pluck(:sport_type).sort
  end

  def show
    @sport_class = SportClass.active
                             .includes(:user, :schedules, :memberships, :coaches)
                             .find(params[:id])

    @my_membership = current_user.memberships.find_by(sport_class: @sport_class)
    @child_memberships = current_user.memberships.current
                                     .where(sport_class: @sport_class)
                                     .where.not(child_id: nil)
                                     .includes(:child)

    # Calculate statistics
    @total_members = @sport_class.memberships.current.count
    @active_members = @sport_class.memberships.where(status: :active).count
    @trial_members = @sport_class.memberships.where(status: :trial).count

    respond_to do |format|
      format.html
      format.json { render json: @sport_class }
    end
  rescue ActiveRecord::RecordNotFound
    flash[:error] = "Kelas olahraga tidak ditemukan"
    redirect_to member_dashboard_path
  end
end

